select m.id, 3, $gfx$true-breakout-vs-fakeout$gfx$, $gfx$True Breakout vs London Fakeout$gfx$, $gfx$Sa London, ang true breakout ay may close lampas at retest; ang fakeout ay bumalik agad sa loob.$gfx$, $gfx$Entry (breakout): tight Asian range; sa London, M15 o H1 close lampas sa range kasabay ng H4 bias, tapos retest confirmation.

