insert into public.training_lessons (module_id, sort, slug, title, tldr, body_md, takeaway, practice_task, status)
select m.id, 1, $gfx$liquidity-pools$gfx$, $gfx$Liquidity: Equal Highs/Lows, Buy-side at Sell-side$gfx$, $gfx$Ang liquidity ay mga lugar kung saan maraming stop orders, gaya ng equal highs at equal lows.$gfx$, $gfx$Buy-side liquidity: nasa itaas ng swing highs at equal highs, kung saan nakalagay ang stops ng shorts at buy orders ng breakout traders. Sell-side liquidity: nasa ilalim ng swing lows at equal lows.

Ang equal highs o lows (dalawa o higit pang tops o bottoms sa halos parehong presyo) ay madalas binabantayan bilang magnet ng presyo.

Ginagamit natin ang liquidity bilang target reference at para maintindihan ang sweeps sa Module 5.

Note: ito ay concept na itinuturo para sa context, hindi standalone na dahilan para mag-entry.

Paalala: start small sa cents account gamit ang maliit na real money na kaya mong mawala. Max 1% risk per trade, at laging may stop loss. Education lang, not financial advice.$gfx$, $gfx$Liquidity = kung saan nakaipon ang stops.$gfx$, $gfx$Mag-mark ng 5 buy-side at 5 sell-side pools sa H1.$gfx$, $gfx$draft$gfx$
