insert into private.placement_quizzes (course_id, questions, disclaimer) select c.id, $gfx$[{"q":"Ano ang trend sa Shared Rules?","options":["H4 HH/HL (o LH/LL) + nasa trend side ng H4 50 EMA + H1 aligned","Price sa itaas ng 20 EMA sa M1","Isang green candle sa M5"],"answer_index":0,"explain":"Ito ang trend definition."},{"q":"Ano ang range?","options":["Defined H4 high/low na may kahit 2 touches bawat side","Kahit anong sideways sa M5","Isang touch lang"],"answer_index":0,"explain":"Range definition."},{"q":"Ano ang confirmation entry?","options":["Entry bago mag-close ang candle","Entry sa level agad","M15/H1 rejection close o break of structure sa direction ng bias"],"answer_index":2,"explain":"Confirmation entries lang."},{"q":"H1 ATR $10. Saan ang max SL bago mag-skip?","options":["$30","$15 (1.5x ATR)","Walang max"],"answer_index":1,"explain":"1.5 × $10 = $15."},{"q":"Ano ang SL buffer?","options":["$1 palagi","Mga 0.2x H1 ATR lagpas sa zone o swing","Exact sa zone edge"],"answer_index":1,"explain":"Lagpas sa zone/swing extreme + mga 0.2x H1 ATR; skip kung kailangan ng SL na lampas 1.5x H1 ATR."},{"q":"Target ay 1.6R sa first logical level. Ano ang gagawin?","options":["Ilipat ang target kahit walang structure","Trade","Walang trade, kulang sa 1:2"],"answer_index":2,"explain":"Min 1:2."},{"q":"$1,000 account, SL $5, 1.00 lot = $100 kada $1. Ano ang lot size sa 1% risk?","options":["1.0","0.02","0.2"],"answer_index":1,"explain":"$10 ÷ ($5 × $100) = 0.02."},{"q":"NFP 9:30 PM PHT (US winter time). Kailan ang blackout?","options":["Buong araw","9:30 hanggang 9:35 PM","8:30 PM hanggang 10:00 PM PHT"],"answer_index":2,"explain":"60 min bago hanggang 30 min pagkatapos."},{"q":"Kailan dapat mag-breakeven?","options":["Agad pagpasok","Kapag kinakabahan","Pagkatapos ng bagong M15/H1 structure"],"answer_index":2,"explain":"Breakeven rule."},{"q":"Ang Fib golden zone ba ay sapat na dahilan para pumasok?","options":["Oo kung 0.618","Oo","Hindi, confluence lang; kailangan ng structure at confirmation"],"answer_index":2,"explain":"Hindi standalone na entry reason."}]$gfx$::jsonb, $gfx$Education lang, not financial advice. Compute your own lot size. Max 1% risk per trade.$gfx$ from public.training_courses c where c.slug = $gfx$gold-advanced-setups$gfx$
