insert into public.training_lessons (module_id, sort, slug, title, tldr, body_md, takeaway, practice_task, status)
select m.id, 1, $gfx$drawing-fib-correctly$gfx$, $gfx$Paano Mag-draw ng Fib nang Tama$gfx$, $gfx$Swing to swing, sa direction ng trend.$gfx$, $gfx$Sa uptrend, i-draw ang Fib mula sa swing low papunta sa swing high ng impulse leg. Sa downtrend, mula sa swing high papunta sa swing low.

Gamitin ang malinaw na H1 impulse leg, hindi random na maliit na galaw.

Kapag mali ang direction ng draw, baligtad ang levels at mali ang buong reading.

Note: ito ay concept na itinuturo para sa context, hindi standalone na dahilan para mag-entry.

Paalala: start small sa cents account gamit ang maliit na real money na kaya mong mawala. Max 1% risk per trade, at laging may stop loss. Education lang, not financial advice.$gfx$, $gfx$Uptrend: low to high. Downtrend: high to low.$gfx$, $gfx$Mag-draw ng Fib sa 5 impulse legs.$gfx$, $gfx$draft$gfx$
