insert into public.training_capstones (course_id, title, rubric, disclaimer) select c.id, $gfx$Gold Strategy Basics Capstone$gfx$, $gfx$["Gumawa ng 3 complete trade plans sa XAUUSD gamit ang Basics setups (historical o chart replay, may date)","Bawat plan: nakasulat ang H4 bias at regime (trend, range, o walang trade)","Bawat plan: H1 zone o structure level na naka-grade gamit ang Zone Quality Checklist","Bawat plan: confirmation condition sa M15 o H1 (rejection close o BOS), hindi entry sa level lang","Bawat plan: SL lagpas sa zone o swing plus mga 0.2x H1 ATR, at hindi lampas sa 1.5x H1 ATR","Bawat plan: first logical target sa next structure, at R:R na kahit 1:2","Bawat plan: lot size na na-compute para max 1% risk, na may formula na ipinakita","Bawat plan: news check, walang entry sa 60 min bago hanggang 30 min pagkatapos ng high-impact USD news","Walang duplicate idea sa parehong zone at walang sabay na long at short","Isang page na review: ano ang malinaw, ano ang hindi pa, at ano ang babaguhin","Naiintindihan ko: Education lang, not financial advice. Compute your own lot size. Max 1% risk per trade."]$gfx$::jsonb, $gfx$Education lang, not financial advice. Compute your own lot size. Max 1% risk per trade.$gfx$ from public.training_courses c where c.slug = $gfx$gold-strategy-basics$gfx$
on conflict (course_id) do update set title = excluded.title, rubric = excluded.rubric, disclaimer = excluded.disclaimer;

